def kategorien_uebernehmen(apps, schema_editor):
    """Vorhandene Leistungen behalten ihre Einordnung: Artikelkategorie wird zur gleichnamigen Leistungskategorie
    (gleichnamige Kategorien fallen zusammen), ein vorhandener EK wird zu den Kosten."""
    Artikel = apps.get_model("stammdaten", "Artikel")
    Leistungskategorie = apps.get_model("stammdaten", "Leistungskategorie")
    for a in Artikel.objects.filter(typ="L", kategorie__isnull=False).select_related("kategorie"):
        kategorie, _ = Leistungskategorie.objects.get_or_create(name=a.kategorie.name, defaults={"nummer": a.kategorie.nummer})
        Artikel.objects.filter(pk=a.pk).update(leistungskategorie=kategorie, kategorie=None)
    for a in Artikel.objects.filter(typ="L", durchschnitts_ek__gt=0):
        Artikel.objects.filter(pk=a.pk).update(kosten=a.durchschnitts_ek.quantize(Decimal("0.01"), rounding=ROUND_HALF_UP))


